<?php
namespace App\Services\Borrowing;
use App\Exceptions\BorrowingException;
use Illuminate\Support\Facades\Http;
final class SupabaseBorrowingService {
 private function client(string $token){$url=rtrim((string)config('supabase.url'),'/');$key=(string)config('supabase.publishable_key');if($url===''||$key===''||$token==='')throw new BorrowingException('Borrowing service is not configured for the authenticated session.',503);return Http::acceptJson()->withHeaders(['apikey'=>$key,'Authorization'=>'Bearer '.$token])->timeout((int)config('supabase.auth_user_timeout',10));}
 private function request(string $token,string $method,string $path,array $query=[],?array $body=null,string $prefer='return=representation'):array{$url=rtrim((string)config('supabase.url'),'/').'/rest/v1/'.$path;$client=$this->client($token)->withHeaders(['Prefer'=>$prefer]);$response=match($method){'GET'=>$client->get($url,$query),'POST'=>$client->post($url,$body??[]),default=>throw new BorrowingException('Unsupported borrowing operation.',405)};if(!$response->successful())$this->fail($response->status(),$response->body());return ['data'=>$response->json()??[],'range'=>$response->header('Content-Range')];}
 private function rpc(string $token,string $name,array $payload):array{$url=rtrim((string)config('supabase.url'),'/').'/rest/v1/rpc/'.$name;$response=$this->client($token)->post($url,$payload);if(!$response->successful())$this->fail($response->status(),$response->body());$data=$response->json();return is_array($data)?$data:[];}
 private function fail(int $status,string $body):never{$raw=strtolower($body);$message=match(true){$status===401=>'Your session is no longer valid. Sign in again.',$status===403=>'Your account does not have permission to perform this borrowing operation.',$status===404=>'The requested borrowing record was not found.',str_contains($raw,'insufficient')=>'There is not enough available inventory to complete this operation.',str_contains($raw,'already been released')=>'This request has already been released.',str_contains($raw,'exceeds')=>'The requested quantity exceeds the available or outstanding quantity.',str_contains($raw,'no longer available')=>'One or more equipment assets are no longer available.',str_contains($raw,'pending')=>'This request is no longer pending.',str_contains($raw,'permission denied')=>'Your account does not have permission to perform this operation.',$status>=500=>'The borrowing service is temporarily unavailable.',default=>'The borrowing operation could not be completed. Check the submitted details.'};throw new BorrowingException($message,in_array($status,[401,403,404,409,422],true)?$status:($status===400?422:502));}
 private function pagination(?string $range,int $page,int $per):array{$total=0;if(is_string($range)&&str_contains($range,'/')){$v=substr($range,strrpos($range,'/')+1);if(ctype_digit($v))$total=(int)$v;}return ['current_page'=>$page,'per_page'=>$per,'total'=>$total,'last_page'=>max(1,(int)ceil($total/max(1,$per)))];}
 public function requests(string $token,array $o):array{$page=$o['page'];$per=$o['per_page'];$q=['select'=>'*,profiles!inner(id,full_name,email,employee_id),borrow_request_items(id,item_id,quantity,remarks,inventory_items!borrow_request_items_item_id_fkey(id,name,item_code,item_type,unit,equipment_assets(id,asset_tag,status,location_id)))','order'=>'requested_at.desc','limit'=>(string)$per,'offset'=>(string)(($page-1)*$per)];if($o['status'])$q['status']='eq.'.$o['status'];if($o['search'])$q['profiles.full_name']='ilike.*'.str_replace(['%','_'],['\\%','\\_'],$o['search']).'*';$r=$this->request($token,'GET','borrow_requests',$q,null,'count=exact');return ['requests'=>$r['data'],'pagination'=>$this->pagination($r['range'],$page,$per)];}
 public function requestDetail(string $token,string $id):array{$r=$this->request($token,'GET','borrow_requests',['select'=>'*,profiles!borrow_requests_borrower_id_fkey(id,full_name,email,employee_id),borrow_request_items(id,item_id,quantity,remarks,inventory_items!borrow_request_items_item_id_fkey(id,name,item_code,item_type,unit,equipment_assets(id,asset_tag,status,location_id))),borrow_transactions(id,released_by,released_at,remarks,profiles!borrow_transactions_released_by_fkey(id,full_name,email),borrow_transaction_items(id,item_id,asset_id,quantity,location_id,inventory_items!borrow_transaction_items_item_id_fkey(id,name,item_code,item_type,unit),equipment_assets!borrow_transaction_items_asset_id_fkey(id,asset_tag,condition,status)))','id'=>'eq.'.$id,'limit'=>'1']);return $r['data'][0]??throw new BorrowingException('Borrowing request not found.',404);}
 public function createRequest(string $token,array $d):array{return $this->rpc($token,'create_borrow_request',['p_expected_return_at'=>$d['expected_return_at'],'p_remarks'=>$d['remarks']??null,'p_items'=>$d['items'],'p_reservation_id'=>$d['reservation_id']??null]);}
 public function cancelRequest(string $token,string $id):array{return $this->rpc($token,'cancel_borrow_request',['p_request_id'=>$id]);}
 public function reviewRequest(string $token,string $id,array $d):array{return $this->rpc($token,'review_borrow_request',['p_request_id'=>$id,'p_decision'=>$d['decision'],'p_remarks'=>$d['remarks']??null]);}
 public function releaseRequest(string $token,string $id,array $d):array{return $this->rpc($token,'release_borrow_request',['p_request_id'=>$id,'p_items'=>$d['items'],'p_remarks'=>$d['remarks']??null]);}
 public function borrowings(string $token,array $o):array{$page=$o['page'];$per=$o['per_page'];$q=['select'=>'*,borrow_requests!inner(id,borrower_id,status,expected_return_at,requested_at,remarks,profiles!borrow_requests_borrower_id_fkey(id,full_name,email,employee_id),borrow_transaction_items(id,item_id,asset_id,quantity,location_id,inventory_items!borrow_transaction_items_item_id_fkey(id,name,item_code,item_type,unit),equipment_assets!borrow_transaction_items_asset_id_fkey(id,asset_tag,condition,status)))','order'=>'released_at.desc','limit'=>(string)$per,'offset'=>(string)(($page-1)*$per)];if($o['overdue']){$q['borrow_requests.expected_return_at']='lt.'.now()->toIso8601String();$q['borrow_requests.status']='in.(approved,partially_returned)';}if($o['status'])$q['borrow_requests.status']='eq.'.$o['status'];$r=$this->request($token,'GET','borrow_transactions',$q,null,'count=exact');return ['borrowings'=>$r['data'],'pagination'=>$this->pagination($r['range'],$page,$per)];}
 public function borrowingDetail(string $token,string $id):array{$r=$this->request($token,'GET','borrow_transactions',['select'=>'*,borrow_requests!inner(id,borrower_id,status,expected_return_at,requested_at,remarks,profiles!borrow_requests_borrower_id_fkey(id,full_name,email,employee_id)),borrow_transaction_items(id,item_id,asset_id,quantity,location_id,inventory_items!borrow_transaction_items_item_id_fkey(id,name,item_code,item_type,unit),equipment_assets!borrow_transaction_items_asset_id_fkey(id,asset_tag,condition,status))','id'=>'eq.'.$id,'limit'=>'1']);return $r['data'][0]??throw new BorrowingException('Borrowing transaction not found.',404);}
 public function returns(string $token,string $id):array{return $this->request($token,'GET','return_transactions',['select'=>'*,profiles!return_transactions_received_by_fkey(id,full_name,email),return_transaction_items(id,item_id,asset_id,quantity,condition,remarks,inventory_items!return_transaction_items_item_id_fkey(id,name,item_code,unit))','transaction_id'=>'eq.'.$id,'order'=>'returned_at.desc'])['data'];}
 public function processReturn(string $token,string $id,array $d):array{return $this->rpc($token,'process_borrow_return',['p_transaction_id'=>$id,'p_items'=>$d['items'],'p_remarks'=>$d['remarks']??null]);}
}